/* Profile UI prototype: editable education and explicit, reviewed material import.
 * Extraction below uses local text rules, not an LLM or PDF parser. */
initialProfile.educations=[];
if(!Array.isArray(state.profile.educations))state.profile.educations=[];
let educationDraft=null,materialReview=null,pendingResumeName=null;
const profileBeforeReset=resetExperienceUi,profileBeforeUndo=undoLast;
const profileBeforeMatch=matchDetail,profileBeforeScreen=screenJob,profileBeforeJd=sourceJdDetail;
const educationDegrees=['本科','硕士','博士','专科','其他'];
resetExperienceUi=function(){profileBeforeReset();educationDraft=null;materialReview=null;pendingResumeName=null};
function educations(){return state.profile.educations||[]}
function blankEducation(){return {id:uid('education'),school:'',degree:'本科',status:'在读',major:'',discipline:'',start:'',end:'',tags:[],courses:'',source:'用户填写',reference:'',confirmed:false}}
function eduSummary(x){return [x.school,x.degree+x.status,x.major,x.end?'预计／实际毕业 '+x.end:'毕业时间待补充'].filter(Boolean).join(' · ')}
function profilePage(){
 const tabs=[['preferences','基本信息与求职意向'],['resume','简历材料'],['experiences','经历与能力']];
 return `${head('个人档案','教育背景与个人经历，共同构成岗位匹配的依据。',`<button class="button" onclick="openVersions()">${icon('history')}档案历史</button>`)}
 <div class="profile-subnav" role="tablist" aria-label="个人档案模块">${tabs.map(([v,n])=>`<button role="tab" aria-selected="${profileSection===v}" class="${profileSection===v?'active':''}" onclick="setProfileSection('${v}')">${n}${v==='experiences'?`<span>${experiences().length}</span>`:''}</button>`).join('')}</div>
 ${profileSection==='preferences'?basicProfileModule():profileSection==='resume'?resumeMaterialModule():experienceModule()}
 <div class="info-note">${icon('shield')}<span>记录仅保存在当前浏览器的当前演示账号。本人核对代表认可事实描述，教育背景和经历均可修改；不代表第三方认证。</span></div>`;
}
function basicProfileModule(){return `<section class="profile-education panel"><div class="section-head"><div><span class="eyebrow">EDUCATION</span><h2>教育背景</h2><p class="muted">本科、硕士分别记录，匹配时保留对应的学校、专业与毕业时间。</p></div><button class="button soft" onclick="openEducationEditor()">${icon('plus')}添加教育经历</button></div><div class="education-list">${educations().length?educations().map(educationCard).join(''):`<div class="profile-empty"><strong>补充学校与专业，让匹配依据更完整</strong><p>当前身份：${esc(state.profile.education)}。学校、院校标签和毕业时间尚未核对。</p><button class="link-btn" onclick="openEducationEditor()">手动添加</button><span>或</span><button class="link-btn" onclick="setProfileSection('resume')">从简历材料提取 ${icon('arrow')}</button></div>`}</div><div class="profile-rule">院校标签仅对照 JD 明确提出的条件或偏好；岗位未要求时，不自行加分或淘汰。</div></section><form class="panel profile-preferences" onsubmit="saveProfile(event)"><h3>基本信息与求职意向</h3><p class="muted">求职条件用于搜索与到岗核对，可以先填写这些信息开始使用。</p><div class="form-grid">${profileFields(state.profile)}</div><div class="form-actions"><button class="button primary" type="submit">保存基本信息与求职意向</button></div></form>`}
function educationCard(x){return `<article class="education-card"><div class="experience-card-head"><div><span class="experience-type">${esc(x.degree)} · ${esc(x.status)}</span><h3>${esc(x.school)}</h3></div><span class="tag ${x.confirmed?'green':'orange'}">${x.confirmed?'本人已核对':'待核对'}</span></div><div class="tags">${(x.tags||[]).map(t=>`<span class="tag purple">${esc(t)}</span>`).join('')}<span class="tag">${esc(x.major||'专业待补充')}</span>${x.discipline?`<span class="tag">${esc(x.discipline)}</span>`:''}</div><p class="education-dates">${esc(x.start||'入学时间待补充')} — ${esc(x.end||'毕业时间待补充')}</p>${x.courses?`<p class="muted">相关课程／研究方向：${esc(x.courses)}</p>`:''}<div class="experience-card-footer"><small>来源：${esc(x.source||'用户填写')} · ${esc(x.updated||'待保存')}</small><div class="inline">${x.sourceText?`<button class="link-btn" onclick="viewProfileSource('education','${x.id}')">查看原文</button>`:''}<button class="link-btn" onclick="openEducationEditor('${x.id}')">编辑</button><button class="link-btn danger-text" onclick="confirmDeleteEducation('${x.id}')">删除</button></div></div></article>`}
function resumeMaterialModule(){const p=state.profile;return `<div class="profile-flow"><div><b>01</b><span>提供简历原文</span></div>${icon('arrow')}<div><b>02</b><span>提取并核对</span></div>${icon('arrow')}<div><b>03</b><span>新增或更新档案</span></div></div><form class="panel" onsubmit="saveProfile(event)"><div class="section-head"><div><h2>简历材料</h2><p class="muted">原文留在这里，确认后的教育和项目进入对应档案。</p></div><span class="tag purple">本地交互演示</span></div><label class="upload-zone" style="display:block">${icon('upload')}<strong>选择文本材料</strong><p>支持 TXT、Markdown；PDF／Word 解析待接入</p><input type="file" accept=".md,.txt,.pdf,.docx" style="display:none" onchange="handleResume(this.files[0])"></label><div class="inline material-source"><span class="tag purple" id="material-name">${icon('file')}${esc(p.resumeName||'粘贴文字材料')}</span><button type="button" class="link-btn" onclick="useExampleResume()">填入示例材料</button></div><div class="field"><label for="resume-text">简历原始文字</label><textarea id="resume-text" name="resume" class="input" style="min-height:270px" placeholder="粘贴教育经历、实习或项目。建议每条经历单独一段。">${esc(p.resume)}</textarea><small>示例格式：教育经历：学校｜学历｜专业｜学科｜入学时间｜毕业时间｜院校标签。</small></div><div class="form-actions"><button class="button" type="submit">保存原始材料</button><button class="button primary" type="button" onclick="beginMaterialReview()">${icon('spark')}提取并核对信息</button></div></form><div class="profile-destinations"><button onclick="setProfileSection('preferences')"><span class="stat-icon">${icon('user')}</span><div><strong>教育背景</strong><small>学校、学历、学科、专业与毕业时间</small></div>${icon('arrow')}</button><button onclick="setProfileSection('experiences')"><span class="stat-icon">${icon('brief')}</span><div><strong>经历与能力</strong><small>项目、实习、研究与本人贡献</small></div>${icon('arrow')}</button></div><div class="info-note">${icon('info')}<span>当前按本地文本规则整理草稿，尚未接入真实模型。提取不会自动写入档案；信息不足可在核对时补充，无法识别时支持手动添加。</span></div>`}
function educationFields(x){return `<div class="form-grid"><div class="field wide"><label>学校名称</label><input class="input" name="school" required maxlength="100" value="${esc(x.school)}" placeholder="填写完整学校名称"></div><div class="field"><label>学历层次</label><select class="select" name="degree">${educationDegrees.map(v=>`<option ${x.degree===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>就读状态</label><select class="select" name="status">${['在读','毕业','其他'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>专业</label><input class="input" name="major" maxlength="80" value="${esc(x.major)}" placeholder="例如：信息管理与信息系统"></div><div class="field"><label>所属学科（可选）</label><input class="input" name="discipline" maxlength="80" value="${esc(x.discipline)}" placeholder="例如：管理学；不确定可留空"></div><div class="field"><label>入学时间（可选）</label><input class="input" type="month" name="start" value="${esc(x.start)}"></div><div class="field"><label>预计／实际毕业时间</label><input class="input" type="month" name="end" value="${esc(x.end)}"></div><div class="field wide"><label>院校标签（可选）</label><div class="education-tags">${['985','211'].map(t=>`<label><input type="checkbox" name="schoolTags" value="${t}" ${(x.tags||[]).includes(t)?'checked':''}>${t}</label>`).join('')}<small>按学校实际情况核对，不确定可都不选。</small></div></div><div class="field wide"><label>相关课程／研究方向（可选）</label><input class="input" name="courses" maxlength="300" value="${esc(x.courses)}" placeholder="用于补充专业相关性，不自动等同实操能力"></div></div>`}
function educationFromValues(v,old){return {...old,school:String(v.school||'').trim().slice(0,100),degree:educationDegrees.includes(v.degree)?v.degree:'其他',status:['在读','毕业','其他'].includes(v.status)?v.status:'在读',major:String(v.major||'').trim().slice(0,80),discipline:String(v.discipline||'').trim().slice(0,80),start:String(v.start||''),end:String(v.end||''),tags:Array.isArray(v.tags)?v.tags.filter(t=>['985','211'].includes(t)):[],courses:String(v.courses||'').trim().slice(0,300)}}
function validEducation(x){return Boolean(x.school)&&(!x.start||/^\d{4}-\d{2}$/.test(x.start))&&(!x.end||/^\d{4}-\d{2}$/.test(x.end))&&(!x.start||!x.end||x.start<=x.end)}
function openEducationEditor(id=null){educationDraft=structuredClone(educations().find(x=>x.id===id)||blankEducation());modal='education';showModal(`${modalHead(id?'编辑教育经历':'添加教育经历','同一条记录内保留对应学校、学历、专业和时间。')}<form onsubmit="saveEducation(event)">${educationFields(educationDraft)}<div class="info-note">${icon('info')}<span>保存表示你已核对这些信息。学校标签不会替代个人能力证据。</span></div><div class="footer"><button type="button" class="button" onclick="closeOverlay()">取消</button><button class="button primary" type="submit">确认并保存教育经历</button></div></form>`,true)}
function markProfileAnalysisStale(){state.jobs.forEach(j=>j.profileAnalysisStale=true)}
function writeProfileChange(title,detail,mutate){const previous=structuredClone(state),undo=lastUndo;archiveProfile(state.profile);mutate();state.profile.updated=today();markProfileAnalysisStale();syncExperienceFlags();if(!addHistory(title,detail)){state=previous;lastUndo=undo;return false}return true}
function saveEducation(e){e.preventDefault();if(!educationDraft)return false;const f=new FormData(e.target),x=educationFromValues({...Object.fromEntries(f),tags:f.getAll('schoolTags')},educationDraft);if(!validEducation(x)){toast('请填写学校，并核对入学与毕业时间。');return false}const old=educations().find(y=>y.id===x.id);x.confirmed=true;x.updated=today();if(!writeProfileChange('已更新教育背景',x.school,()=>{state.profile.educations=[...educations().filter(y=>y.id!==x.id),x];lastUndo={kind:'education',before:old?structuredClone(old):null,afterId:x.id}}))return false;educationDraft=null;closeOverlay();toast('教育经历已保存，相关分析待更新。',true);return true}
function confirmDeleteEducation(id){const x=educations().find(y=>y.id===id);if(!x)return;modal='education-delete';showModal(`${modalHead('删除这条教育经历？',x.school)}<p>删除后不再用于匹配，可撤回。岗位池与实际投递记录保留。</p><div class="footer"><button class="button" onclick="closeOverlay()">取消</button><button class="button danger" onclick="deleteEducation('${id}')">确认删除</button></div>`)}
function deleteEducation(id){const old=educations().find(x=>x.id===id);if(!old)return false;if(!writeProfileChange('已删除教育经历',old.school,()=>{state.profile.educations=educations().filter(x=>x.id!==id);lastUndo={kind:'education',before:structuredClone(old),afterId:id}}))return false;closeOverlay();toast('教育经历已删除，可撤回。',true);return true}
undoLast=function(){if(lastUndo?.kind!=='education'){profileBeforeUndo();return}const u=lastUndo;if(!writeProfileChange('已撤回教育经历修改',u.before?.school||'移除新增记录',()=>{state.profile.educations=educations().filter(x=>x.id!==u.afterId);if(u.before)state.profile.educations.push(structuredClone(u.before));lastUndo=null}))return;render();toast('已恢复修改前的教育经历。')};
function viewProfileSource(kind,id){const x=(kind==='education'?educations():experiences()).find(y=>y.id===id);if(!x)return;modal='profile-source';showModal(`${modalHead('材料原文',x.materialName||x.source||'个人材料')}<blockquote class="profile-source-text">${esc(x.sourceText||x.reference||'暂无原文')}</blockquote><p class="muted">这是提取时保留的原文片段；修改档案不会改写这段来源。</p><div class="footer"><button class="button" onclick="closeOverlay()">关闭</button></div>`,true)}
const profileExperienceCard=experienceCard;
experienceCard=function(x){const html=profileExperienceCard(x);return x.sourceText?html.replace('<div class="experience-card-footer"><small>',`<button class="link-btn profile-source-link" onclick="viewProfileSource('experience','${x.id}')">${icon('file')}查看提取原文</button><div class="experience-card-footer"><small>`):html};
function demoResumeText(){return '教育经历：示例A大学｜本科毕业｜信息管理与信息系统｜管理学｜2022-09｜2026-06｜211\n教育经历：示例B大学｜硕士｜教育学｜教育学｜2026-09｜2029-06｜985、211\n\n项目：InternPilot 实习岗位匹配助手\n本人工作：完成需求分析、UI 设计和匹配流程设计。\n工具与方法：绘制泳道图，制作网页交互原型。\n产出：项目 PRD 和网页交互原型。\n\n项目：用户评论分类项目\n本人工作：使用 Python 对用户评论进行分类。\n工具与方法：整理价格、功能与体验问题。\n产出：分类结果表和问题汇总。'}
useExampleResume=function(){const el=document.getElementById('resume-text');if(el)el.value=demoResumeText();pendingResumeName='教育与项目示例.txt';const name=document.getElementById('material-name');if(name)name.textContent=pendingResumeName;toast('示例已填入编辑框，尚未保存或写入档案。')};
handleResume=function(f){if(!f)return;const ext=f.name.split('.').pop().toLowerCase();if(!['md','txt','pdf','docx'].includes(ext)||f.size>10*1024*1024){toast('请选择小于 10 MB 的文本材料。');return}if(['pdf','docx'].includes(ext)){toast('PDF／Word 解析尚未接入，请粘贴文字或选择 TXT、Markdown。');return}const origin=state;const reader=new FileReader();reader.onerror=()=>toast('读取失败，请重试或粘贴文字。');reader.onload=()=>{if(state!==origin)return;const el=document.getElementById('resume-text');if(!el)return;el.value=String(reader.result);pendingResumeName=f.name;const name=document.getElementById('material-name');if(name)name.textContent=f.name;toast('文字已读入，核对后可保存或提取。')};reader.readAsText(f)};
saveProfile=function(e){e.preventDefault();const f=new FormData(e.target);if(!f.has('resume')){const p={...state.profile};for(const k of ['name','education','direction','city','days','months','start'])if(f.has(k))p[k]=String(f.get(k)).trim();if(!p.name||!p.direction||!Number(p.days)||!Number(p.months)){toast('请填写称呼和必要的求职条件。');return false}if(!writeProfileChange('已更新基本信息与求职意向',p.direction,()=>{state.profile={...p,days:Number(p.days),months:Number(p.months)}}))return false;render();toast('条件已保存，规则已重新核对，相关旧分析待更新。');return true}const text=String(f.get('resume')||'').trim();if(!text){toast('请先提供材料文字。');return false}if(!writeProfileChange('已保存简历原文','原文更新，已有教育与经历不会自动覆盖',()=>{state.profile.resume=text;state.profile.resumeName=pendingResumeName||state.profile.resumeName||'粘贴文字材料'}))return false;pendingResumeName=null;render();toast('原文已保存。可继续提取并核对，已有经历保持原样。');return true};
function extractMaterialLocally(text){
 const a=[],lines=text.split(/\r?\n/);let current=null;
 const flush=()=>{if(current)a.push(current);current=null};
 for(const raw of lines){const line=raw.trim().replace(/^#{1,6}\s*/,'');if(!line)continue;
  if(/^教育经历[:：]/.test(line)){flush();const body=line.replace(/^教育经历[:：]\s*/,''),parts=body.split(/[|｜]/).map(x=>x.trim()),x=blankEducation();
   if(parts.length>=3){x.school=parts[0];x.degree=educationDegrees.find(d=>parts[1].includes(d))||'其他';x.status=/毕业/.test(parts[1])?'毕业':'在读';x.major=parts[2]||'';x.discipline=parts[3]||'';x.start=/^\d{4}-\d{2}$/.test(parts[4]||'')?parts[4]:'';x.end=/^\d{4}-\d{2}$/.test(parts[5]||'')?parts[5]:'';x.tags=['985','211'].filter(t=>(parts[6]||'').includes(t))}
   else{x.school=(body.match(/[\u4e00-\u9fa5A-Za-z]+(?:大学|学院)/)||[''])[0];x.degree=educationDegrees.find(d=>body.includes(d))||'其他';x.tags=['985','211'].filter(t=>body.includes(t))}
   a.push({kind:'education',record:x,raw,line:raw,mode:'new',targetId:''});continue;
  }
  if(/^(项目[一二三四五六七八九十\d]*|项目经历|实习经历|科研经历|研究经历|校园活动)[:：]/.test(line)){flush();const title=line.replace(/^[^:：]+[:：]\s*/,''),x=blankExperience();x.title=title.slice(0,80);x.type=/^实习/.test(line)?'实习经历':/^(科研|研究)/.test(line)?'研究经历':/^校园/.test(line)?'校园活动':'个人项目';x.responsibility='';current={kind:'experience',record:x,raw,mode:'new',targetId:''};continue}
  if(current){current.raw+='\n'+raw;if(/^(本人工作|本人职责|职责)[:：]/.test(line))current.record.responsibility=line.replace(/^[^:：]+[:：]\s*/,'');else if(/^(工具与方法|方法|工具)[:：]/.test(line))current.record.methods=line.replace(/^[^:：]+[:：]\s*/,'');else if(/^(产出|成果|结果)[:：]/.test(line))current.record.result=line.replace(/^[^:：]+[:：]\s*/,'');else current.record.responsibility+=(current.record.responsibility?'\n':'')+line}
 }
 flush();return a.slice(0,30);
}
function beginMaterialReview(){const text=(document.getElementById('resume-text')?.value||state.profile.resume||'').trim();if(!text){toast('请先粘贴简历文字，或填入示例材料。');return}const items=extractMaterialLocally(text);materialReview={items,index:0,text,name:pendingResumeName||state.profile.resumeName||'粘贴文字材料',saved:0,skipped:0};showMaterialReview()}
function materialTargetList(item){return item.kind==='education'?educations():experiences()}
function importModeFields(item){const list=materialTargetList(item);return `<fieldset class="import-mode"><legend>这条信息如何进入档案？</legend><label><input type="radio" name="importMode" value="new" ${item.mode==='new'?'checked':''} onchange="changeImportMode(this.value)"><span><strong>新增一条${item.kind==='education'?'教育':'经历'}记录</strong><small>之前没有保存过这段经历时选择。</small></span></label><label><input type="radio" name="importMode" value="update" ${item.mode==='update'?'checked':''} ${list.length?'':'disabled'} onchange="changeImportMode(this.value)"><span><strong>更新已有记录</strong><small>${list.length?'这是同一段经历的新进展或新表述。':'暂无已有记录，先新增即可。'}</small></span></label>${item.mode==='update'?`<div class="field"><label>选择需要更新的记录</label><select class="select" name="targetId" onchange="changeImportTarget(this.value)"><option value="">请选择已有记录</option>${list.map(x=>`<option value="${x.id}" ${item.targetId===x.id?'selected':''}>${esc(item.kind==='education'?eduSummary(x):x.title)}</option>`).join('')}</select></div>${item.targetId?`<div class="import-before"><strong>原记录</strong><p>${esc(item.kind==='education'?eduSummary(list.find(x=>x.id===item.targetId)||{}):(list.find(x=>x.id===item.targetId)?.responsibility||''))}</p><small>下方内容保存后将更新这条记录。请保留需要的信息，其他记录不会删除。</small></div>`:''}`:''}</fieldset>`}
function importExperienceFields(x){return `<div class="form-grid"><div class="field wide"><label>经历名称</label><input class="input" name="title" required maxlength="80" value="${esc(x.title)}"></div><div class="field"><label>经历类型</label><select class="select" name="type">${experienceTypes.map(t=>`<option ${x.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>实际使用情况</label><select class="select" name="level">${Object.entries(experienceLevels).map(([v,n])=>`<option value="${v}" ${x.level===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field wide"><label>本人工作</label><textarea class="input" name="responsibility" required maxlength="1500">${esc(x.responsibility)}</textarea></div><div class="field wide"><label>具体方法／工具（可选）</label><textarea class="input" name="methods" maxlength="1000">${esc(x.methods)}</textarea></div><div class="field wide"><label>产出／结果（可选）</label><textarea class="input" name="result" maxlength="1000">${esc(x.result)}</textarea></div><div class="field wide"><label>关联技能（可选）</label><input class="input" name="skills" maxlength="150" value="${esc(x.skills.join('、'))}" placeholder="只记录有依据的技能，不确定可留空"></div></div>`}
function showMaterialReview(){if(!materialReview)return;const r=materialReview,item=r.items[r.index];modal='material-review';
 if(!item){showModal(`${modalHead(r.items.length?'本次核对完成':'未识别到可整理的经历',r.items.length?`已保存 ${r.saved} 条，跳过 ${r.skipped} 条。`:'当前演示只按带标题的文本段落整理，可调整文字格式或手动添加。')}<div class="info-note">${icon('info')}<span>${r.items.length?'新简历中未出现的旧记录均予以保留。':'使用“项目：名称”和“教育经历：学校｜学历｜专业”标题可以体验核对流程。'}</span></div><div class="footer"><button class="button" onclick="finishMaterialReview('resume')">返回材料</button><button class="button soft" onclick="finishMaterialReview('preferences')">查看教育背景</button><button class="button primary" onclick="finishMaterialReview('experiences')">查看经历与能力</button></div>`,true);return}
 showModal(`${modalHead('核对提取信息',`${r.index+1} / ${r.items.length} · ${item.kind==='education'?'保存到基本信息中的教育背景':'保存到经历与能力'}`)}<div class="import-progress"><span class="tag purple">文本规则演示 · 非模型输出</span><small>未确认的信息不会写入档案</small></div><details class="import-original" open><summary>查看本条材料原文</summary><blockquote>${esc(item.raw)}</blockquote></details><form id="material-review-form" onsubmit="commitMaterialItem(event)">${importModeFields(item)}<h3 class="import-edit-title">核对并修改本次内容</h3>${item.kind==='education'?educationFields(item.record):importExperienceFields(item.record)}<div class="info-note">${icon('info')}<span>空白字段代表材料未说明，请按事实补充。更新已有记录时请逐项核对；保存后可从档案历史恢复。</span></div><div class="footer"><button type="button" class="button" onclick="cancelMaterialReview()">结束核对</button><button type="button" class="button" onclick="skipMaterialItem()">跳过这条</button><button type="submit" class="button primary">${item.mode==='update'?'确认更新原记录':'确认新增到档案'}</button></div></form>`,true);
}
function captureImportEdits(){const r=materialReview,item=r?.items[r.index],form=document.getElementById('material-review-form');if(!item||!form)return;const f=new FormData(form),v=Object.fromEntries(f);item.record=item.kind==='education'?educationFromValues({...v,tags:f.getAll('schoolTags')},item.record):{...item.record,...readExperienceFields(v,item.record)};item.mode=v.importMode||item.mode;item.targetId=v.targetId||item.targetId}
function changeImportMode(mode){captureImportEdits();const item=materialReview?.items[materialReview.index];if(!item||!['new','update'].includes(mode))return;item.mode=mode;showMaterialReview()}
function changeImportTarget(id){captureImportEdits();const item=materialReview?.items[materialReview.index];if(!item)return;item.targetId=id;showMaterialReview()}
function commitMaterialItem(e){e.preventDefault();if(!materialReview)return false;captureImportEdits();const r=materialReview,item=r.items[r.index];if(!item)return false;const list=materialTargetList(item),old=item.mode==='update'?list.find(x=>x.id===item.targetId):null;if(item.mode==='update'&&!old){toast('请选择需要更新的已有记录。');return false}const x=item.record;if(item.kind==='education'?!validEducation(x):!x.title||!x.responsibility){toast(item.kind==='education'?'请填写学校，并核对入学与毕业时间。':'请填写经历名称和本人工作。');return false}
 const record={...structuredClone(x),id:old?.id||x.id,confirmed:true,updated:today(),source:'简历材料提取 · 本人已核对',reference:r.name,sourceText:item.raw,materialName:r.name};
 if(!writeProfileChange(item.mode==='update'?'已更新材料中的已有记录':'已确认材料中的新增记录',record.school||record.title,()=>{const key=item.kind==='education'?'educations':'experiences';state.profile[key]=[...(state.profile[key]||[]).filter(y=>y.id!==record.id),record];state.profile.resume=r.text;state.profile.resumeName=r.name;lastUndo={kind:item.kind==='education'?'education':'experience',before:old?structuredClone(old):null,afterId:record.id}}))return false;
 r.saved++;r.index++;pendingResumeName=null;showMaterialReview();toast('已保存这条记录，其余条目仍需核对。',true);return true;
}
function skipMaterialItem(){if(!materialReview)return;materialReview.skipped++;materialReview.index++;showMaterialReview()}
function cancelMaterialReview(){materialReview=null;closeOverlay();toast('已结束核对，已确认的记录保留，未确认内容未入档。')}
function finishMaterialReview(section){materialReview=null;closeOverlay();profileSection=section;nav('profile')}
function educationRequirements(j){if(j.educationRequirements)return j.educationRequirements;if(!j.manual&&j.id===1)return {degree:'本科',studying:true,major:'',tags:['985','211'],tagMode:'preferred',raw:'本科或硕士在读，985／211 院校优先；专业不限。'};if(!j.manual)return {degree:'本科',studying:true,major:'',tags:[],tagMode:'none',raw:'本科或硕士在读；院校与专业未作明确限制。'};return {degree:null,studying:false,major:'',tags:[],tagMode:'none',raw:'原始 JD 的教育条件尚待核对，未自动推断学历、专业或院校门槛。'}}
function educationAssessment(j){const req=educationRequirements(j),a=educations().filter(x=>x.confirmed),rows=[];const ranks={专科:0,本科:1,硕士:2,博士:3};let excluded=false,unknown=false;
 if(!req.degree){rows.push({name:'学历与在读状态',status:'需要确认',tone:'orange',detail:'岗位教育要求未完整解析，请对照原文核对。'});unknown=true}
 else if(!a.length){rows.push({name:'学历与在读状态',status:'需要确认',tone:'orange',detail:'尚无本人核对的教育经历，请补充学校、学历与状态。'});unknown=true}
 else {const qualified=a.filter(x=>ranks[x.degree]>=ranks[req.degree]&&(!req.studying||x.status==='在读'));const ok=qualified.length>0,ambiguous=a.some(x=>ranks[x.degree]===undefined||x.status==='其他');excluded=!ok&&!ambiguous;unknown=!ok&&ambiguous;rows.push({name:'学历与在读状态',status:ok?'已知条件满足':ambiguous?'需要确认':'条件不符',tone:ok?'green':ambiguous?'orange':'red',detail:`要求${req.degree}及以上${req.studying?'在读':''}；${a.map(eduSummary).join('；')}`})}
 if(req.major){const relevant=a.some(x=>(x.major+' '+x.discipline+' '+x.courses).includes(req.major));rows.push({name:'学科与专业',status:relevant?'有相关信息':'相关性待确认',tone:relevant?'green':'orange',detail:`岗位要求：${req.major}；${a.length?a.map(x=>[x.school,x.major,x.discipline].filter(Boolean).join(' · ')).join('；'):'个人专业信息待补充'}。不按专业名称不同直接淘汰。`});if(!relevant)unknown=true}else rows.push({name:'学科与专业',status:'未设明确限制',tone:'',detail:'保留专业背景；岗位未提出时，不自行增加专业门槛。'});
 if(req.tags?.length){const hit=a.some(x=>x.tags?.some(t=>req.tags.includes(t))),missing=!a.length||a.every(x=>!x.tags?.length);if(req.tagMode==='required'){if(missing)unknown=true;else if(!hit)excluded=true}rows.push({name:'院校背景',status:hit?'有对应背景':missing?'标签待确认':req.tagMode==='preferred'?'未命中优先项':'条件不符',tone:hit?'green':req.tagMode==='preferred'?'':'orange',detail:`${req.tags.join('／')} ${req.tagMode==='preferred'?'优先，不作为淘汰门槛':'为 JD 明确要求'}；依据对应教育经历，不按最高学历的学校覆盖本科记录。`})}else rows.push({name:'院校背景',status:'未设明确限制',tone:'',detail:'JD 未明确要求 985／211，不自行加分或淘汰。'});
 if(req.graduation){const hit=a.some(x=>x.end?.startsWith(String(req.graduation))),missing=a.some(x=>!x.end)||!a.length;if(!hit){if(missing)unknown=true;else excluded=true}rows.push({name:'毕业届别',status:hit?'已知条件满足':missing?'时间待补充':'届别不符',tone:hit?'green':'orange',detail:`要求 ${req.graduation} 届，按每段教育经历的毕业时间核对。`})}
 return {req,rows,kind:excluded?'excluded':unknown?'confirm':'suggested'};
}
function educationMatchPanel(j){const a=educationAssessment(j);return `<section class="education-match"><div class="section-head"><div><span class="eyebrow">EDUCATION MATCH</span><h2>教育背景匹配</h2></div><button class="link-btn" onclick="openEducationModule()">管理教育背景 ${icon('arrow')}</button></div><div class="evidence-label">岗位教育要求 · ${j.manual?'原文待核对':'合成 JD'}</div><div class="evidence-quote">${esc(a.req.raw||'以岗位原文明确要求为准')}</div>${a.rows.map(x=>`<div class="education-match-row"><div><strong>${x.name}</strong><span class="tag ${x.tone}">${x.status}</span></div><p>${esc(x.detail)}</p></div>`).join('')}<small class="muted">依据当前确认的教育记录即时核对；示例总分不变。专业相关性与未解析条件仍需人工确认。</small></section>`}
function openEducationModule(){closeOverlay();profileSection='preferences';nav('profile')}
matchDetail=function(j){return educationMatchPanel(j)+profileBeforeMatch(j)};
screenJob=function(j){const original=profileBeforeScreen(j),a=educationAssessment(j);if(a.kind==='excluded')return {kind:'excluded',label:'条件不符',tone:'red',reasons:[...original.reasons,...a.rows.filter(x=>x.tone==='red'||x.status==='届别不符'||x.status==='条件不符').map(x=>x.name+'：'+x.detail)]};if(a.kind==='confirm'&&original.kind!=='excluded')return {kind:'confirm',label:'需要确认',tone:'orange',reasons:[...original.reasons.filter(x=>!x.startsWith('已知到岗条件符合')),'教育背景或专业相关性待核对']};return original};
sourceJdDetail=function(j){const html=profileBeforeJd(j);return j.manual?html:html+`<div class="jd-body"><h3>教育背景要求 · 合成示例</h3><p>${esc(educationRequirements(j).raw)}</p></div>`};
